mapper.select:
select Row_Number() OVER (ORDER BY rjep.PROD_ID desc) as id,rjep.PROD_ID as prodId,rjep.PROD_NAME as prodName
from REP_JOB_EXCLUDE_PRO rjep
where rjep.JOB_ID=#{jobId,jdbcType=VARCHAR}

select  COUNT(JOB_ID)
from REP_JOB
where JOB_ID = #{jobId,jdbcType=VARCHAR}
or JOB_NAME = #{jobName,jdbcType=VARCHAR}
